export const config = {
  runtime: 'edge',
};

// =============================================================================
// POR QUE ESTE HTML ESTA EMBEBIDO EN BASE64 EN VEZ DE SER UN ARCHIVO ESTATICO
// =============================================================================
//
// Vercel evalua archivos estaticos ANTES que rewrites/redirects, sin
// excepcion, para cualquier ruta donde exista un archivo fisico coincidente.
// Esto se comprobo en producción DOS VECES el mismo dia (2026-09-16):
//   1. sitio/_app-electric-side/index.html -> HTTP 200 sin auth (bypass)
//   2. sitio/electric-side/index.html      -> HTTP 200 sin auth (mismo bug,
//      reintroducido al restaurar el archivo para arreglar el punto 1)
//
// No existe combinacion de rewrites/redirects/headers en vercel.json que
// proteja una ruta que ademas tiene un archivo estatico real en esa misma
// ruta. La unica arquitectura que funciona es que el contenido NUNCA exista
// como archivo en el arbol de salida de Vercel (todo lo que esta dentro de
// sitio/ se deploya como estatico salvo las funciones en sitio/api/).
//
// Por eso el HTML completo de Electric Side (Gestion Interna V07) vive
// como constante base64 aqui mismo, dentro del bundle JS de esta funcion.
// Es codigo, no un archivo servible: la unica forma de obtenerlo es pasar
// la validacion de Basic Auth de este mismo handler.
//
// REGLAS QUE NUNCA HAY QUE ROMPER:
//
// 1. NUNCA volver a crear ninguno de estos paths (ni ese contenido en
//    cualquier otro path fisico dentro de sitio/), aunque sea "temporal":
//      - sitio/electric-side/index.html
//      - sitio/_app-electric-side/index.html
//      - public/electric-side/index.html
//      - public/_app-electric-side/index.html
//      - cualquier archivo .html con este contenido en cualquier carpeta
//        que Vercel deploye como estatica
//
// 2. Para ACTUALIZAR el contenido de la app: editar
//    tools/electric-side/source.html (fuente editable, FUERA de sitio/,
//    Vercel nunca la deploya porque el root directory del proyecto es
//    "sitio") y correr `node tools/electric-side/build.mjs`. Ese script
//    regenera el bloque de abajo y verifica que decode(base64) sea
//    exactamente igual al source.html, byte a byte. NUNCA editar el
//    string base64 a mano.
//
// 3. El rewrite en sitio/vercel.json (/electric-side/(:path*) ->
//    /api/protect-electric-side/(:path*)) es lo que hace llegar el
//    request hasta aca. Sin archivo fisico que lo bypasee, ese rewrite
//    SIEMPRE se evalua primero.
//
// Contenido verificado: 100% autocontenido (logo y fotos ya son data:
// URIs embebidos dentro del propio HTML/JS) -- no hay assets JS/CSS/
// imagen externos que dependan de una ruta publica separada.
// =============================================================================

// === GENERATED:ELECTRIC_SIDE_HTML_B64:START ===
const ELECTRIC_SIDE_HTML_B64 = "";
// === GENERATED:ELECTRIC_SIDE_HTML_B64:END ===

function decodeHtml() {
  return Buffer.from(ELECTRIC_SIDE_HTML_B64, 'base64').toString('utf-8');
}

export default async function handler(request) {
  // FAIL-CLOSED: Validate env vars exist before any other logic
  const expectedUser = process.env.ELECTRIC_SIDE_USER;
  const expectedPassword = process.env.ELECTRIC_SIDE_PASSWORD;

  if (!expectedUser || !expectedPassword) {
    console.error('SECURITY: ELECTRIC_SIDE_USER or ELECTRIC_SIDE_PASSWORD not configured');
    return new Response('Service Unavailable', {
      status: 503,
      headers: {
        'cache-control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
        'content-type': 'text/plain',
        'retry-after': '3600',
      },
    });
  }

  // Check for Authorization header
  const authHeader = request.headers.get('authorization');

  if (!authHeader || !authHeader.startsWith('Basic ')) {
    return new Response('Unauthorized', {
      status: 401,
      headers: {
        'www-authenticate': 'Basic realm="Electric Side"',
        'cache-control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
        'content-type': 'text/plain',
      },
    });
  }

  try {
    // Decode Basic Auth credentials
    const base64Credentials = authHeader.slice(6);
    const credentials = Buffer.from(base64Credentials, 'base64').toString('utf-8');
    const [username, password] = credentials.split(':');

    // Validate credentials
    if (username !== expectedUser || password !== expectedPassword) {
      return new Response('Unauthorized', {
        status: 401,
        headers: {
          'www-authenticate': 'Basic realm="Electric Side"',
          'cache-control': 'no-store, no-cache, must-revalidate, proxy-revalidate',
          'content-type': 'text/plain',
        },
      });
    }

    // Credentials valid - serve the embedded app content directly.
    // No fetch to origin: there is no static file to fetch, and self-fetching
    // this same rewritten path would loop back into this same handler.
    return new Response(decodeHtml(), {
      status: 200,
      headers: {
        'content-type': 'text/html; charset=utf-8',
        'cache-control': 'private, no-cache, no-store, must-revalidate',
        'x-protected-by': 'basic-auth',
        'x-robots-tag': 'noindex, nofollow',
      },
    });
  } catch (error) {
    console.error('Auth error:', error);
    return new Response('Invalid Authorization header', {
      status: 400,
      headers: {
        'www-authenticate': 'Basic realm="Electric Side"',
        'content-type': 'text/plain',
      },
    });
  }
}
